// Entry point of the Cloudflare Worker.
// The logic is in src/charleywong/WorkerMain.hx, compiled to worker/charleywong.js by worker.hxml.
// The data is generated by `node staticSite.js build`.
import haxe from "./charleywong.js";
import indexText from "../dist/worker/index.txt";
import entitiesData from "../dist/worker/entities.bin";

const { CharleyWong } = haxe;

// Parse the data during Worker startup instead of in the first request.
CharleyWong.init(indexText, entitiesData);

export default {
    fetch(request, env, ctx) {
        return CharleyWong.fetch(request, env, ctx);
    },
};
